#include <stdio.h>
#include <stdlib.h>

#define MAXK 305
#define MAXS 2705
#define INF 1000000000

int main() {
    int N, K, T;
    scanf("%d %d %d", &N, &K, &T);

    int P[305], G[305], s[305];
    int sumP = 0;

    for (int i = 1; i <= N; i++) {
        scanf("%d", &P[i]);
        sumP += P[i];
    }

    for (int i = 1; i <= N; i++) {
        scanf("%d", &G[i]);
    }

    int cnt = 0;
    for (int i = 1; i <= N; i++) {
        if (G[i] == 1) {
            s[cnt++] = i;
        }
    }

    int maxScore = 9 * K;
    if (maxScore > sumP) maxScore = sumP;

    static int dp[MAXK][MAXS];

    for (int i = 0; i <= K; i++) {
        for (int w = 0; w <= maxScore; w++) {
            dp[i][w] = INF;
        }
    }

    dp[0][0] = 0;

    for (int p = 1; p <= N; p++) {
        int val = P[p];
        int maxj = p < K ? p : K;

        for (int j = maxj; j >= 1; j--) {
            int add = abs(s[j - 1] - p);
            int maxw = maxScore - val;
            if (maxw < 0) continue;

            int srcMax = 9 * (j - 1);
            if (srcMax > maxw) srcMax = maxw;

            for (int w = 0; w <= srcMax; w++) {
                if (dp[j - 1][w] != INF) {
                    int nc = dp[j - 1][w] + add;
                    int idx = w + val;
                    if (nc < dp[j][idx]) {
                        dp[j][idx] = nc;
                    }
                }
            }
        }
    }

    int ans = 0;
    for (int w = maxScore; w >= 0; w--) {
        if (dp[K][w] <= T) {
            ans = w;
            break;
        }
    }

    printf("%d\n", ans);
    return 0;
}
